<?php
require_once __DIR__ . '/../../includes/auth.php';requireLogin();if(!hasRole('admin','gerente','financeiro')){http_response_code(403);exit('Acesso negado.');}if($_SERVER['REQUEST_METHOD']!=='POST'||!hash_equals($_SESSION['csrf_financeiro']??'',$_POST['csrf']??'')){http_response_code(400);exit('Requisição inválida.');}$db=getDB();$id=(int)($_POST['id']??0);$acao=$_POST['acao']??'';if($acao==='pagar'){$db->prepare("UPDATE contas SET status='pago',data_pagamento=CURDATE() WHERE id=? AND status<>'cancelado'")->execute([$id]);$_SESSION['msg']='Pagamento registrado.';}elseif($acao==='cancelar'){$db->prepare("UPDATE contas SET status='cancelado' WHERE id=?")->execute([$id]);$_SESSION['msg']='Lançamento cancelado.';}header('Location:index.php');
